1	package posemap
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"testing"
8	)
9	
10	// 本文件为“整段导入在落盘失败时整体失败”补充一项回归保障，专门覆盖两种
11	// 路标变化发生在同一段内时的情形：既有仍有效的路标在本段继续合并观测
12	// （原地更新当前出现），同时一个此前已失效的路标在与旧位置明显不同的
13	// 地点再次被观测（追加一次全新出现）。本段内容本身完全合法——时间严格
14	// 递增、数值有限、观测距离满足合并上限——仅因本地地图文件无法更新而
15	// 保存失败。此时已确认数据必须保持导入前的状态：位姿、有效路标的均值
16	// 与计数、失效路标的旧出现（位置、次数、失效时间与原因）都不变，查不到
17	// 任何部分结果；失败返回的是保存错误而不是成功结果，也不能把合法内容
18	// 误报成时间倒退或路标冲突。保存条件恢复后，以同一段标识再次提交同一
19	// 内容必须正常成功（前一次失败不占用段标识），且结果与这段内容从未经历
20	// 失败、直接成功导入完全一致。
21	//
22	// 统一几何（初始位姿 (0,0)、朝向 0、初始方差 0.5、合并上限 5）：
23	//
24	// 已保存的种子段（段标识 seg-seed）：
25	//
26	//	t=100 位姿 (0,0)，方差 0.6：A 本地 (1,0) → 世界 (1,0)；B 本地 (2,0) → (2,0)
27	//	t=200 位姿 (0,0)，方差 0.7：A 再观测一次 (1,0)
28	//
29	// 因而 A 为仍有效的第 1 次出现，均值 (1,0)、计数 2、首次观测时间 100；
30	// B 同为第 1 次出现、计数 1，随后在 t=200 被失效（原因 sign removed），
31	// 旧出现保留在 (2,0)。
32	//
33	// 待导入段（段标识 seg-next）为连续四帧沿世界 X 轴的运动，朝向始终为 0：
34	//
35	//	t=300 DX=1 → (1,0)，方差 0.9：A 本地 (0,0) → (1,0)
36	//	t=400 DX=1 → (2,0)，方差 1.1：A 本地 (0,0) → (2,0)；
37	//	             B 本地 (0,10) → (2,10)（与旧位置 (2,0) 相距 10，明显不同）
38	//	t=500 DX=1 → (3,0)，方差 1.3：B 本地 (0,10) → (3,10)
39	//	t=600 DX=1 → (4,0)，方差 1.7：无观测
40	//
41	// 全部观测按现有规则均可接受：
42	//
43	//	A 以已提交的 (1,0)、计数 2 为固定起点：(1,0) 距离 0 并入后计数 3、
44	//	均值仍为 (1,0)；(2,0) 与均值相距 1 ≤ 5，并入后计数 4、均值 (1.25,0)。
45	//	B 的最近一次出现已失效，(2,10) 是第 2 次出现的首条观测（不做距离
46	//	判定），首次观测时间 400、计数 1；(3,10) 与 (2,10) 相距 1 ≤ 5，
47	//	并入后计数 2、均值 (2.5,10)。旧出现 (2,0) 不参与合并。
48	//
49	// 直接成功导入本段时末位姿为 t=600 (4,0)、朝向 0、方差 1.7，涉及路标
50	// [A B]。
51	
52	// saveFailureMixedConfig 是这组场景的地图配置。
53	func saveFailureMixedConfig() Config {
54		return Config{InitialTime: 0, InitialVariance: 0.5, MaxInterval: 1000, MergeDistance: 5.0}
55	}
56	
57	// seedMixedLandmarkMap 在 path 处创建地图并保存好“种子段 + B 失效”的
58	// 前置状态，返回的地图当前位姿停在 t=200 (0,0)、方差 0.7：A 仍有效
59	// （(1,0)、计数 2），B 的第 1 次出现已失效（(2,0)、计数 1、失效时间 200）。
60	func seedMixedLandmarkMap(t *testing.T, path string) *Map {
61		t.Helper()
62		m, err := Create(path, saveFailureMixedConfig())
63		if err != nil {
64			t.Fatalf("Create: %v", err)
65		}
66		if _, err := m.ImportSegment(Segment{ID: "seg-seed", Frames: []Frame{
67			{Time: 100, DX: 0, MoveVariance: 0.1, Observations: []Observation{
68				{ID: "A", X: 1, Y: 0},
69				{ID: "B", X: 2, Y: 0},
70			}},
71			{Time: 200, DX: 0, MoveVariance: 0.1, Observations: []Observation{
72				{ID: "A", X: 1, Y: 0},
73			}},
74		}}); err != nil {
75			t.Fatalf("seed import: %v", err)
76		}
77		if _, err := m.Invalidate(Invalidation{ID: "inv-b", Reason: "sign removed", Landmarks: []string{"B"}}); err != nil {
78			t.Fatalf("invalidate B: %v", err)
79		}
80		return m
81	}
82	
83	// mixedLandmarkNextSegment 构造待导入的四帧合法轨迹段。
84	func mixedLandmarkNextSegment() Segment {
85		return Segment{ID: "seg-next", Frames: []Frame{
86			{Time: 300, DX: 1, MoveVariance: 0.2, Observations: []Observation{
87				{ID: "A", X: 0, Y: 0},
88			}},
89			{Time: 400, DX: 1, MoveVariance: 0.2, Observations: []Observation{
90				{ID: "A", X: 0, Y: 0},
91				{ID: "B", X: 0, Y: 10},
92			}},
93			{Time: 500, DX: 1, MoveVariance: 0.2, Observations: []Observation{
94				{ID: "B", X: 0, Y: 10},
95			}},
96			{Time: 600, DX: 1, MoveVariance: 0.4},
97		}}
98	}
99	
100	// breakSavingAtPath 让目标路径无法被原子替换：删掉地图文件并在原路径建
101	// 一个同名目录，saveReplace 的 rename 因此失败（EISDIR），而此前的地图
102	// 内容也不再能通过该路径更新。
103	func breakSavingAtPath(t *testing.T, path string) {
104		t.Helper()
105		if err := os.Remove(path); err != nil {
106			t.Fatalf("remove map file: %v", err)
107		}
108		if err := os.Mkdir(path, 0o755); err != nil {
109			t.Fatalf("mkdir over map path: %v", err)
110		}
111	}
112	
113	// restoreSavingAtPath 恢复保存条件：移除占位目录，并把当前内存状态重新
114	// 落盘为正常地图文件。
115	func restoreSavingAtPath(t *testing.T, m *Map, path string) {
116		t.Helper()
117		if err := os.Remove(path); err != nil {
118			t.Fatalf("remove directory at map path: %v", err)
119		}
120		if err := m.saveReplace(); err != nil {
121			t.Fatalf("restore map file: %v", err)
122		}
123	}
124	
125	// expectAppearance 断言某次出现的编号、有效状态、首次观测时间、位置、
126	// 计数与失效信息与期望一致。
127	func expectAppearance(t *testing.T, what string, got Appearance, want Appearance) {
128		t.Helper()
129		if got.Number != want.Number || got.Active != want.Active ||
130			got.HasFirstSeen != want.HasFirstSeen || got.FirstSeenTime != want.FirstSeenTime {
131			t.Fatalf("%s header = %+v, want number=%d active=%t firstSeen(%t,%d)",
132				what, got, want.Number, want.Active, want.HasFirstSeen, want.FirstSeenTime)
133		}
134		if got.Landmark.ID != want.Landmark.ID || got.Landmark.Count != want.Landmark.Count {
135			t.Fatalf("%s landmark = %+v, want id=%q count=%d",
136				what, got.Landmark, want.Landmark.ID, want.Landmark.Count)
137		}
138		approxEq(t, what+" x", got.Landmark.X, want.Landmark.X)
139		approxEq(t, what+" y", got.Landmark.Y, want.Landmark.Y)
140		if got.InvalidTime != want.InvalidTime || got.InvalidReason != want.InvalidReason ||
141			got.InvalidOpID != want.InvalidOpID {
142			t.Fatalf("%s invalid info = (%d,%q,%q), want (%d,%q,%q)",
143				what, got.InvalidTime, got.InvalidReason, got.InvalidOpID,
144				want.InvalidTime, want.InvalidReason, want.InvalidOpID)
145		}
146	}
147	
148	// wantPreImportPose 是导入前段末位姿（也是失败后所有失败段帧时间的
149	// PoseAt 查询应取得的位姿）。
150	func wantPreImportPose() Pose {
151		return Pose{Time: 200, X: 0, Y: 0, Heading: 0, Variance: 0.7}
152	}
153	
154	// assertPreImportState 断言地图完全处于“种子段 + B 失效”的导入前状态，
155	// 失败回滚后与从未导入过 seg-next 的参照地图都必须满足它。
156	func assertPreImportState(t *testing.T, m *Map) {
157		t.Helper()
158		pre := wantPreImportPose()
159	
160		// 当前位姿：时间、位置、朝向、方差均为导入前末位姿。
161		cur, err := m.CurrentPose()
162		if err != nil {
163			t.Fatalf("CurrentPose: %v", err)
164		}
165		expectPose(t, "current pose", cur, pre)
166	
167		// 按失败段内各帧时间（以及段前缝隙）查询，都只能取得导入前最后一份
168		// 位姿；更早的历史位姿也保持原样。
169		for _, at := range []int64{250, 300, 400, 500, 600, 1 << 40} {
170			p, err := m.PoseAt(at)
171			if err != nil {
172				t.Fatalf("PoseAt(%d): %v", at, err)
173			}
174			expectPose(t, "pose after failed segment time", p, pre)
175		}
176		p100, err := m.PoseAt(100)
177		if err != nil {
178			t.Fatalf("PoseAt(100): %v", err)
179		}
180		expectPose(t, "earlier pose", p100, Pose{Time: 100, X: 0, Y: 0, Heading: 0, Variance: 0.6})
181	
182		// 区域查询：只有仍有效的 A，且是原来的位置与计数；B 已失效不显示，
183		// B 的新出现位置 (2..3, 9..11) 一处也查不到。
184		lms, err := m.LandmarksInRect(allRect())
185		if err != nil {
186			t.Fatalf("LandmarksInRect: %v", err)
187		}
188		if len(lms) != 1 || lms[0].ID != "A" {
189			t.Fatalf("active landmarks = %v, want only A", lms)
190		}
191		if lms[0].Count != 2 {
192			t.Fatalf("A count = %d, want unchanged 2", lms[0].Count)
193		}
194		approxEq(t, "A x", lms[0].X, 1)
195		approxEq(t, "A y", lms[0].Y, 0)
196		newBRect, err := m.LandmarksInRect(Rect{MinX: 2, MinY: 9, MaxX: 3, MaxY: 11})
197		if err != nil {
198			t.Fatalf("LandmarksInRect new B area: %v", err)
199		}
200		if len(newBRect) != 0 {
201			t.Fatalf("new B occurrence queryable after failed save: %v", newBRect)
202		}
203	
204		// A：仍是唯一一次有效出现，位置与计数不变。
205		hA, err := m.LandmarkAppearances("A")
206		if err != nil {
207			t.Fatalf("LandmarkAppearances(A): %v", err)
208		}
209		if len(hA.Appearances) != 1 {
210			t.Fatalf("A appearances = %+v, want exactly 1", hA.Appearances)
211		}
212		expectAppearance(t, "A occ1", hA.Appearances[0], Appearance{
213			Number: 1, Active: true, FirstSeenTime: 100, HasFirstSeen: true,
214			Landmark: Landmark{ID: "A", X: 1, Y: 0, Count: 2},
215		})
216	
217		// B：仍只有旧的第 1 次出现，保留自己的位置、次数、失效时间与原因，
218		// 没有新增出现编号，也没有被重新标成有效。
219		hB, err := m.LandmarkAppearances("B")
220		if err != nil {
221			t.Fatalf("LandmarkAppearances(B): %v", err)
222		}
223		if len(hB.Appearances) != 1 {
224			t.Fatalf("B appearances = %+v, want exactly 1 (old, invalidated)", hB.Appearances)
225		}
226		expectAppearance(t, "B occ1", hB.Appearances[0], Appearance{
227			Number: 1, Active: false, FirstSeenTime: 100, HasFirstSeen: true,
228			Landmark:      Landmark{ID: "B", X: 2, Y: 0, Count: 1},
229			InvalidTime:   200,
230			InvalidReason: "sign removed",
231			InvalidOpID:   "inv-b",
232		})
233	}
234	
235	// TestImportSegmentSaveFailureRollsBackMergedAndReappearingLandmarks 验证：
236	// 一段同时“给有效路标合并新观测”和“让失效路标重新出现”的合法轨迹，仅因
237	// 本地地图文件无法更新而保存失败时，整段失败、无任何可查询的部分结果；
238	// 恢复后以同一标识重试成功，结果与该内容直接成功导入完全一致。
239	func TestImportSegmentSaveFailureRollsBackMergedAndReappearingLandmarks(t *testing.T) {
240		dir := t.TempDir()
241		path := filepath.Join(dir, "map.pose")
242		m := seedMixedLandmarkMap(t, path)
243		t.Cleanup(func() { _ = m.Close() })
244	
245		// ---- 制造保存失败并提交合法段 ----
246		breakSavingAtPath(t, path)
247		seg := mixedLandmarkNextSegment()
248		res, err := m.ImportSegment(seg)
249		if err == nil {
250			t.Fatal("import with unupdatable map file unexpectedly succeeded")
251		}
252		// 必须是保存错误：不能是 *RejectError（不能把合法内容误报成时间倒退、
253		// 路标冲突等），也不能返回成功导入结果。
254		if r, ok := AsRejectError(err); ok {
255			t.Fatalf("valid segment rejected as %s: %v", r.Kind, err)
256		}
257		if res.EndPose.Time != 0 || res.LandmarkIDs != nil {
258			t.Fatalf("failed import returned result %+v, want zero result", res)
259		}
260	
261		// ---- 失败后：已确认数据完整保持导入前状态 ----
262		assertPreImportState(t, m)
263	
264		// ---- 恢复保存条件，以同一段标识提交同一内容 ----
265		restoreSavingAtPath(t, m, path)
266		res, err = m.ImportSegment(seg)
267		if err != nil {
268			t.Fatalf("retry same segment id after save restored: %v", err)
269		}
270		// 有效路标只增加本段实际观测的次数；失效路标只新增下一次出现。
271		expectPose(t, "retry end pose", res.EndPose,
272			Pose{Time: 600, X: 4, Y: 0, Heading: 0, Variance: 1.7})
273		if len(res.LandmarkIDs) != 2 || res.LandmarkIDs[0] != "A" || res.LandmarkIDs[1] != "B" {
274			t.Fatalf("retry landmark ids = %v, want [A B]", res.LandmarkIDs)
275		}
276	
277		// 末位姿与段内各帧均已生效，数值与直接推演一致。
278		cur, _ := m.CurrentPose()
279		expectPose(t, "current after retry", cur, res.EndPose)
280		for _, want := range []Pose{
281			{Time: 300, X: 1, Y: 0, Heading: 0, Variance: 0.9},
282			{Time: 400, X: 2, Y: 0, Heading: 0, Variance: 1.1},
283			{Time: 500, X: 3, Y: 0, Heading: 0, Variance: 1.3},
284			{Time: 600, X: 4, Y: 0, Heading: 0, Variance: 1.7},
285		} {
286			p, err := m.PoseAt(want.Time)
287			if err != nil {
288				t.Fatalf("PoseAt(%d) after retry: %v", want.Time, err)
289			}
290			expectPose(t, "pose after retry", p, want)
291		}
292	
293		// A：计数只增加本段实际观测的 2 次（2 → 4），均值并入两条新观测。
294		hA, _ := m.LandmarkAppearances("A")
295		if len(hA.Appearances) != 1 {
296			t.Fatalf("A appearances after retry = %+v, want 1", hA.Appearances)
297		}
298		expectAppearance(t, "A occ1 after retry", hA.Appearances[0], Appearance{
299			Number: 1, Active: true, FirstSeenTime: 100, HasFirstSeen: true,
300			Landmark: Landmark{ID: "A", X: 1.25, Y: 0, Count: 4},
301		})
302	
303		// B：旧出现仍失效、不参与新位置合并；只新增第 2 次出现，编号接在旧
304		// 记录之后，计数从本次实际观测重新开始，首次观测时间取本段首次看到
305		// 它的帧时间 400。
306		hB, _ := m.LandmarkAppearances("B")
307		if len(hB.Appearances) != 2 {
308			t.Fatalf("B appearances after retry = %+v, want 2", hB.Appearances)
309		}
310		expectAppearance(t, "B occ1 after retry", hB.Appearances[0], Appearance{
311			Number: 1, Active: false, FirstSeenTime: 100, HasFirstSeen: true,
312			Landmark:      Landmark{ID: "B", X: 2, Y: 0, Count: 1},
313			InvalidTime:   200,
314			InvalidReason: "sign removed",
315			InvalidOpID:   "inv-b",
316		})
317		expectAppearance(t, "B occ2 after retry", hB.Appearances[1], Appearance{
318			Number: 2, Active: true, FirstSeenTime: 400, HasFirstSeen: true,
319			Landmark: Landmark{ID: "B", X: 2.5, Y: 10, Count: 2},
320		})
321	
322		// 区域查询现在同时给出 A 的合并结果与 B 的新出现。
323		lms, _ := m.LandmarksInRect(allRect())
324		if len(lms) != 2 {
325			t.Fatalf("active landmarks after retry = %v, want A and B", lms)
326		}
327		aLM, ok := findLandmark(lms, "A")
328		if !ok || aLM.Count != 4 {
329			t.Fatalf("A in rect = %+v ok=%t", aLM, ok)
330		}
331		approxEq(t, "A rect x", aLM.X, 1.25)
332		bLM, ok := findLandmark(lms, "B")
333		if !ok || bLM.Count != 2 {
334			t.Fatalf("B in rect = %+v ok=%t", bLM, ok)
335		}
336		approxEq(t, "B rect x", bLM.X, 2.5)
337		approxEq(t, "B rect y", bLM.Y, 10)
338	
339		// ---- 与“同内容直接成功导入、从未经历失败”的参照地图逐值比对 ----
340		refPath := filepath.Join(t.TempDir(), "ref.pose")
341		ref := seedMixedLandmarkMap(t, refPath)
342		t.Cleanup(func() { _ = ref.Close() })
343		refRes, err := ref.ImportSegment(mixedLandmarkNextSegment())
344		if err != nil {
345			t.Fatalf("reference import: %v", err)
346		}
347		expectPose(t, "reference end pose", refRes.EndPose, res.EndPose)
348		if len(refRes.LandmarkIDs) != len(res.LandmarkIDs) {
349			t.Fatalf("reference ids = %v, want %v", refRes.LandmarkIDs, res.LandmarkIDs)
350		}
351		for i, id := range refRes.LandmarkIDs {
352			if res.LandmarkIDs[i] != id {
353				t.Fatalf("ids differ at %d: %q vs %q", i, res.LandmarkIDs[i], id)
354			}
355		}
356		for _, at := range []int64{0, 100, 200, 300, 400, 500, 600} {
357			got, gerr := m.PoseAt(at)
358			want, werr := ref.PoseAt(at)
359			if gerr != nil || werr != nil {
360				t.Fatalf("PoseAt(%d) errors: %v %v", at, gerr, werr)
361			}
362			expectPose(t, "parity pose vs reference", got, want)
363		}
364		for _, id := range []string{"A", "B"} {
365			got, _ := m.LandmarkAppearances(id)
366			want, _ := ref.LandmarkAppearances(id)
367			if len(got.Appearances) != len(want.Appearances) {
368				t.Fatalf("%s occurrence count = %d, want %d", id, len(got.Appearances), len(want.Appearances))
369			}
370			for i := range got.Appearances {
371				expectAppearance(t, "parity "+id+" appearance", got.Appearances[i], want.Appearances[i])
372			}
373		}
374		refLms, _ := ref.LandmarksInRect(allRect())
375		if len(refLms) != len(lms) {
376			t.Fatalf("rect counts differ: %v vs %v", lms, refLms)
377		}
378		for _, want := range refLms {
379			got, ok := findLandmark(lms, want.ID)
380			if !ok || got.Count != want.Count {
381				t.Fatalf("rect %s = %+v ok=%t, want count %d", want.ID, got, ok, want.Count)
382			}
383			approxEq(t, "parity rect x", got.X, want.X)
384			approxEq(t, "parity rect y", got.Y, want.Y)
385		}
386	
387		// 正常导入行为保持不变：同段同内容重复提交直接返回首次结果。
388		again, err := m.ImportSegment(mixedLandmarkNextSegment())
389		if err != nil {
390			t.Fatalf("duplicate import after retry: %v", err)
391		}
392		expectPose(t, "duplicate end pose", again.EndPose, res.EndPose)
393	
394		// ---- 关闭重开：落盘内容与内存一致，失败的那次没落任何痕迹 ----
395		if err := m.Close(); err != nil {
396			t.Fatalf("close: %v", err)
397		}
398		reopened, err := Open(path)
399		if err != nil {
400			t.Fatalf("reopen: %v", err)
401		}
402		defer reopened.Close()
403		cur, _ = reopened.CurrentPose()
404		expectPose(t, "reopened current pose", cur, res.EndPose)
405		hB, _ = reopened.LandmarkAppearances("B")
406		if len(hB.Appearances) != 2 || hB.Appearances[0].Active ||
407			hB.Appearances[0].InvalidReason != "sign removed" ||
408			!hB.Appearances[1].Active || hB.Appearances[1].FirstSeenTime != 400 ||
409			hB.Appearances[1].Landmark.Count != 2 {
410			t.Fatalf("B after reopen = %+v", hB.Appearances)
411		}
412		approxEq(t, "reopened B occ2 x", hB.Appearances[1].Landmark.X, 2.5)
413		approxEq(t, "reopened B occ2 y", hB.Appearances[1].Landmark.Y, 10)
414		hA, _ = reopened.LandmarkAppearances("A")
415		if len(hA.Appearances) != 1 || !hA.Appearances[0].Active ||
416			hA.Appearances[0].Landmark.Count != 4 {
417			t.Fatalf("A after reopen = %+v", hA.Appearances)
418		}
419		approxEq(t, "reopened A x", hA.Appearances[0].Landmark.X, 1.25)
420	
421		// 重开后用同段标识再提交同一内容，仍按已保存段返回首次结果而非被
422		// 误判成冲突——证明失败尝试没有污染段标识。
423		dup, err := reopened.ImportSegment(mixedLandmarkNextSegment())
424		if err != nil {
425			t.Fatalf("duplicate import after reopen: %v", err)
426		}
427		if dup.EndPose.Time != 600 || len(dup.LandmarkIDs) != 2 {
428			t.Fatalf("reopened duplicate result = %+v", dup)
429		}
430		// 陌生标识仍然不存在。
431		if _, err := reopened.LandmarkAppearances("ZZ"); !errors.Is(err, ErrLandmarkNotFound) {
432			t.Fatalf("unexpected landmark ZZ: %v", err)
433		}
434	}
435

