package posemap

import (
	"math"
	"sort"
)

// poseShift 描述一次回环校正对轨迹施加的同一次刚体重定位：锚点落到目标
// 位置、朝向归一到 [-π,π)；从锚点到末帧的其余帧与锚点一起平移旋转，保留
// 各帧相对锚点的位置关系与朝向差。提交校正（Correct）与打开地图时的校正
// 记录几何核对（validateLoaded，见 persistence.go）共用这同一份规则与
// 运算次序，两处对“校正后位置与朝向”的理解因此始终一致。
type poseShift struct {
	x, y          float64 // 目标位置，即锚点校正后位置
	heading       float64 // 目标朝向归一到 [-π,π)，即锚点校正后朝向
	anchorX       float64 // 锚点校正前位置
	anchorY       float64
	anchorHeading float64 // 锚点校正前朝向
	dHeading      float64 // 归一后的最短朝向差，即各帧叠加的旋转角
	cosD, sinD    float64 // 旋转角的余弦与正弦
	tx, ty        float64 // 纯平移校正（旋转角为 0）时各轴的平移量
	identity      bool    // 只调方差的恒等校正：位置与朝向保持原值
}

// newPoseShift 按提交目标与锚点校正前位姿构造重定位。目标朝向先归一，
// 旋转角取归一后的最短朝向差。目标位置与锚点原位置完全相同、目标朝向归
// 一后与原朝向等价（旋转角为 0）时是恒等校正：几何上没有任何平移或旋
// 转，校正前后位姿必须完全相同。恒等校正不能套用旋转平移公式——公式会
// 先求相对锚点的偏移，轨迹横跨 ±1e308 这类大坐标时该差值先溢出为
// ±Inf、再参与浮点运算退化为 NaN，使本应成功的校正被误判为数值异常；
// 恒等校正直接保留原位姿。纯平移校正（旋转角为 0 但位置有移动）同理不
// 能套用该公式：它按“各轴平移量 = 目标轴坐标 − 锚点原轴坐标”逐轴平移，
// 只要各轴平移量与校正后坐标有限，轨迹横跨多大坐标都不会凭空溢出。
func newPoseShift(tgt CorrectionTarget, anchorBefore Pose) poseShift {
	heading := normalizeAngle(tgt.Heading)
	dHeading := normalizeAngle(heading - anchorBefore.Heading)
	return poseShift{
		x:             tgt.X,
		y:             tgt.Y,
		heading:       heading,
		anchorX:       anchorBefore.X,
		anchorY:       anchorBefore.Y,
		anchorHeading: anchorBefore.Heading,
		dHeading:      dHeading,
		cosD:          math.Cos(dHeading),
		sinD:          math.Sin(dHeading),
		tx:            tgt.X - anchorBefore.X,
		ty:            tgt.Y - anchorBefore.Y,
		identity:      dHeading == 0 && tgt.X == anchorBefore.X && tgt.Y == anchorBefore.Y,
	}
}

// apply 计算一帧校正后的位置与朝向：恒等校正原样保留校正前值；纯平移校
// 正（旋转角为 0）按各轴平移量逐轴平移；其余情形把校正前相对锚点的偏移
// 随锚点一起旋转平移，朝向叠加同一旋转角并归一到 [-π,π)。帧时间与方差
// 不属于几何规则，由调用方处理。
//
// 纯平移不套用“先求相对锚点偏移再加回目标位置”的通用公式：锚点与某帧
// 分处很大的正、负坐标时（如 ±1e308），该偏移先溢出为 ±Inf，即使两轴
// 平移量与校正后坐标都有限也会被误判为数值异常。逐轴平移时，某轴平移量
// 为零则该轴坐标原样保留（连 -0 也不会被写成 +0），另一轴的平移不影响
// 它；某轴平移量本身溢出为无穷时，校正后坐标随之非有限，仍由调用方按既
// 有数值异常规则整次拒绝。
//
// 朝向按“目标朝向 + 该校正前相对锚点的朝向差”计算，而不是“校正前朝向 +
// 旋转角”：二者在数学上（模 2π）等价，但后者先把目标朝向与锚点朝向相减
// 再加回，当目标朝向远小于锚点朝向时（例如锚点朝向 1 弧度、目标朝向
// 1e-20 弧度），目标朝向会在相减时被锚点朝向的精度吞掉，校正结果退化为
// 零——有限且可表示的非零目标朝向必须作为实际定位结果保留。按相对朝向差
// 计算时，锚点及原本与锚点朝向完全相同的帧恰好得到目标朝向本身，存在其
// 他朝向差的帧仍保留与锚点的相对方向。
func (s poseShift) apply(before Pose) (x, y, heading float64) {
	if s.identity {
		return before.X, before.Y, before.Heading
	}
	if s.dHeading == 0 {
		// 纯平移：逐轴平移，不经过相对锚点的偏移（见大段注释）。与锚点
		// 原轴坐标相同的帧（含锚点自身）直接取目标轴坐标：锚点必须准确
		// 采用提交目标，且校正前同轴坐标相同的帧校正后也必须相同，不能
		// 因“先减后加”的末位舍入彼此偏离。
		x, y = before.X, before.Y
		if before.X == s.anchorX {
			x = s.x
		} else if s.tx != 0 {
			x = before.X + s.tx
		}
		if before.Y == s.anchorY {
			y = s.y
		} else if s.ty != 0 {
			y = before.Y + s.ty
		}
		return x, y, normalizeAngle(s.heading + (before.Heading - s.anchorHeading))
	}
	dx := before.X - s.anchorX
	dy := before.Y - s.anchorY
	return s.x + s.cosD*dx - s.sinD*dy,
		s.y + s.sinD*dx + s.cosD*dy,
		normalizeAngle(s.heading + (before.Heading - s.anchorHeading))
}

// Correct 提交一次已确认回环校正。
//
// req.ID 必须非空；req.Anchor 必须准确命中一个已导入帧的时间（不能是
// 初始位姿，也不借用历史查询得到的最近一帧）；目标位姿数值必须有限、
// 目标方差必须非负。命中后，锚点帧采用提交的位姿；从锚点到提交时末帧
// 的轨迹整体平移并旋转（保持这些帧在校正前彼此的相对位置与朝向，时间
// 不变，朝向归一到既有范围）；锚点之后每帧的方差等于目标方差加上锚点
// 之后至该帧的原运动方差累计值。更早的位姿不变。
//
// 受影响帧中的路标观测随新位姿改变地图位置；更早观测的地图位置不变。
// 同一路标仍按全部已接受观测、依原时间与同帧输入次序做增量平均并遵守
// 合并距离限制；观测次数不变。若校正后出现路标冲突，整次校正拒绝并说
// 明冲突帧时间与路标。输入或校正结果含非有限数值同样拒绝；观测转换到
// 地图坐标后溢出为 NaN/无穷时按数值异常拒绝，说明该观测所在帧的实际
// 时间、路标标识与出现编号，而不是误报为距离冲突。
//
// 同一标识以相同内容重复提交返回首次结果且不再修改数据；同一标识不同
// 内容明确拒绝。任何拒绝或保存失败都不改变轨迹、路标与既有校正记录。
// 旧文件缺少逐帧观测来源时，覆盖其历史范围的校正返回 RejectNoBasis。
func (m *Map) Correct(req Correction) (CorrectionRecord, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return CorrectionRecord{}, ErrClosed
	}
	st := m.state

	// 已保存校正：相同内容直接返回首次记录；不同内容明确拒绝。
	// 不做任何校验或状态变更，即使其后又提交过其他校正。
	if hash, ok := st.corrIndex[req.ID]; ok {
		if hash == canonicalCorrectionHash(req.Anchor, req.Target) {
			return cloneRecord(st.correctionRecordByID(req.ID)), nil
		}
		return CorrectionRecord{}, &RejectError{Kind: RejectCorrectionMismatch, Landmark: req.ID, HasLandmark: true}
	}

	if req.ID == "" {
		return CorrectionRecord{}, &RejectError{Kind: RejectEmptyID}
	}
	tgt := req.Target
	if !isFinite(tgt.X) || !isFinite(tgt.Y) || !isFinite(tgt.Heading) || !isFinite(tgt.Variance) {
		return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
	}
	if tgt.Variance < 0 {
		return CorrectionRecord{}, &RejectError{Kind: RejectNegativeVariance, Time: req.Anchor, HasTime: true}
	}

	// 锚点必须准确命中已导入帧：trajectory[0] 是初始位姿，不能校正。
	anchorIdx := -1
	for j := 1; j < len(st.trajectory); j++ {
		if st.trajectory[j].Time == req.Anchor {
			anchorIdx = j
			break
		}
	}
	if anchorIdx < 0 {
		return CorrectionRecord{}, &RejectError{Kind: RejectAnchorNotFound, Time: req.Anchor, HasTime: true}
	}
	end := len(st.trajectory) - 1

	// 受影响范围内每一帧都必须有逐帧依据（旧文件没有，不能靠推测校正）。
	for k := anchorIdx - 1; k < len(st.sources); k++ {
		if st.sources[k] == nil {
			return CorrectionRecord{}, &RejectError{Kind: RejectNoBasis, Time: req.Anchor, HasTime: true}
		}
	}

	oldAnchor := st.trajectory[anchorIdx]
	// 锚点到末帧的整体平移旋转规则（含只调方差的恒等情形）与打开地图时
	// 的记录几何核对共享同一实现，见上方 poseShift。
	shift := newPoseShift(tgt, oldAnchor)

	// ---- 在副本上推演新位姿，真实状态此时保持不变 ----
	next := append([]Pose(nil), st.trajectory...)
	accumVar := tgt.Variance
	for j := anchorIdx; j <= end; j++ {
		old := st.trajectory[j]
		if j > anchorIdx {
			accumVar += st.sources[j-1].moveVariance
		}
		x, y, heading := shift.apply(old)
		np := Pose{
			Time:     old.Time,
			X:        x,
			Y:        y,
			Heading:  heading,
			Variance: accumVar,
		}
		if !isFinite(np.X) || !isFinite(np.Y) || !isFinite(np.Heading) || !isFinite(np.Variance) {
			return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
		}
		next[j] = np
	}

	// 重放器：观测按帧时间归入当时那次出现、旧观测固定贡献作为起点、
	// 逐条重建位置的规则与打开地图时的核对共享同一实现（见 replay.go）。
	replay := newObservationReplay(st.config.MergeDistance)
	for id, lm := range st.landmarks {
		replay.track(id, lm.occurrenceWindows())
	}
	// 重放帧序列：受影响帧（锚点至末帧）用校正后位姿，更早帧用原位姿；
	// 旧文件帧没有逐帧依据，其观测已计入对应出现的固定旧贡献，这里按
	// 空观测帧处理。
	frames := make([]replayFrame, 0, end)
	for j := 1; j <= end; j++ {
		var obs []Observation
		if src := st.sources[j-1]; src != nil {
			obs = src.observations
		}
		frames = append(frames, replayFrame{time: st.trajectory[j].Time, pose: next[j], observations: obs})
	}

	// 受影响的路标出现：在受影响帧中被观测到的全部（标识，出现编号）。
	// 回环校正跨越同一路标的多次出现时，各次出现分别聚合、分别遵守合并
	// 距离限制；已接受观测必然属于某次出现。
	affected := replay.observed(frames[anchorIdx-1:])
	affectedKeys := make([]occurrenceKey, 0, len(affected))
	for k := range affected {
		affectedKeys = append(affectedKeys, k)
	}
	sort.Slice(affectedKeys, func(i, j int) bool {
		if affectedKeys[i].id != affectedKeys[j].id {
			return affectedKeys[i].id < affectedKeys[j].id
		}
		return affectedKeys[i].num < affectedKeys[j].num
	})

	// 逐“出现”登记固定旧贡献：旧文件第 1 次出现的既有观测无法重放，
	// 其贡献固定为文件中的聚合值（位置不随校正改变）；其余观测随帧序列
	// 重放。同一路标的不同出现互不参与彼此的合并。
	for _, k := range affectedKeys {
		occ := st.landmarks[k.id].appearances[k.num-1]
		replay.seed(k.id, k.num, occ.legacyCount, occ.legacyMX, occ.legacyMY)
	}
	// 目标、原始观测与校正后位姿都有限，转换结果仍可能因数值过大
	// 溢出为 NaN/无穷。与导入一致：数值异常优先于距离冲突，按
	// non_finite 拒绝并指出该观测所在帧的实际时间、路标标识与
	// 其所属的出现编号（不是锚点时间），无论该次出现此前是否已有
	// 观测、记录仍有效还是已失效。
	if rej := replay.replay(frames); rej != nil {
		switch rej.reason {
		case replayNonFinite:
			return CorrectionRecord{}, &RejectError{
				Kind:          RejectNonFinite,
				Time:          rej.time,
				HasTime:       true,
				Landmark:      rej.id,
				HasLandmark:   true,
				Occurrence:    rej.num,
				HasOccurrence: true,
			}
		case replayConflict:
			return CorrectionRecord{}, &RejectError{
				Kind:          RejectLandmarkConflict,
				Time:          rej.time,
				HasTime:       true,
				Landmark:      rej.id,
				HasLandmark:   true,
				Occurrence:    rej.num,
				HasOccurrence: true,
			}
		default:
			// 已接受观测必然属于某个已登记出现；归属失败说明内存不变量
			// 被破坏，不可能由本包产生，按损坏处理而非半提交。
			return CorrectionRecord{}, ErrCorrupt
		}
	}
	for _, k := range affectedKeys {
		a := replay.agg(k.id, k.num)
		occ := st.landmarks[k.id].appearances[k.num-1]
		if !isFinite(a.x) || !isFinite(a.y) {
			return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
		}
		if a.count != occ.count {
			// 内存不变量被破坏不可能由本包写出，按损坏处理而非半提交。
			return CorrectionRecord{}, ErrCorrupt
		}
	}

	// ---- 组装校正前后快照（记录不可变） ----
	rec := &CorrectionRecord{
		ID:        req.ID,
		Anchor:    req.Anchor,
		Target:    tgt,
		EndTime:   st.trajectory[end].Time,
		Poses:     make([]PoseChange, 0, end-anchorIdx+1),
		Landmarks: make([]LandmarkChange, 0, len(affectedKeys)),
	}
	for j := anchorIdx; j <= end; j++ {
		rec.Poses = append(rec.Poses, PoseChange{Before: st.trajectory[j], After: next[j]})
	}
	for _, k := range affectedKeys {
		occ := st.landmarks[k.id].appearances[k.num-1]
		a := replay.agg(k.id, k.num)
		rec.Landmarks = append(rec.Landmarks, LandmarkChange{
			ID:         k.id,
			Occurrence: k.num,
			Before:     Landmark{ID: k.id, X: occ.x, Y: occ.y, Count: occ.count},
			After:      Landmark{ID: k.id, X: a.x, Y: a.y, Count: a.count},
		})
	}

	// ---- 全部校验通过：暂存提交并落盘；落盘失败精确回滚 ----
	oldTraj := append([]Pose(nil), st.trajectory...)
	type occSnapshot struct {
		key  occurrenceKey
		occ  *occurrenceState
		x, y float64
	}
	oldOcc := make([]occSnapshot, 0, len(affectedKeys))
	for _, k := range affectedKeys {
		occ := st.landmarks[k.id].appearances[k.num-1]
		oldOcc = append(oldOcc, occSnapshot{key: k, occ: occ, x: occ.x, y: occ.y})
	}
	oldCorrLen := len(st.corrections)

	st.trajectory = next
	for _, s := range oldOcc {
		a := replay.agg(s.key.id, s.key.num)
		s.occ.x, s.occ.y = a.x, a.y
	}
	st.corrections = append(st.corrections, rec)
	st.corrIndex[req.ID] = canonicalCorrectionHash(req.Anchor, tgt)

	if err := m.saveReplace(); err != nil {
		st.trajectory = oldTraj
		for _, s := range oldOcc {
			s.occ.x, s.occ.y = s.x, s.y
		}
		st.corrections = st.corrections[:oldCorrLen]
		delete(st.corrIndex, req.ID)
		return CorrectionRecord{}, err
	}
	return cloneRecord(rec), nil
}

// Corrections 返回按提交次序排列的成功校正记录副本。记录一经生成永不
// 被后续校正改写；后续校正只是以当时最新状态为起点生成新记录。
func (m *Map) Corrections() ([]CorrectionRecord, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.closed {
		return nil, ErrClosed
	}
	out := make([]CorrectionRecord, 0, len(m.state.corrections))
	for _, rec := range m.state.corrections {
		out = append(out, cloneRecord(rec))
	}
	return out, nil
}

func (st *mapState) correctionRecordByID(id string) *CorrectionRecord {
	for _, rec := range st.corrections {
		if rec.ID == id {
			return rec
		}
	}
	return nil
}

func cloneRecord(rec *CorrectionRecord) CorrectionRecord {
	if rec == nil {
		return CorrectionRecord{}
	}
	cp := *rec
	cp.Poses = append([]PoseChange(nil), rec.Poses...)
	cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
	return cp
}

// Package posemap 是本地定位与地图的本地基线，提供可由本地程序调用的
// 二维轨迹与路标功能：创建地图、按段导入有序帧、查询历史位姿与矩形区域
// 内的路标，并把全部数据持久化到本地文件，关闭后重新打开结果一致。
package posemap

import (
	"errors"
	"math"
	"strconv"
)

// Config 描述创建一份新地图时的初始状态与两个阈值。
//
// 位置单位为米，时间单位为整数毫秒，朝向单位为弧度。初始位置方差
// InitialVariance 必须非负；最大帧间隔 MaxInterval（毫秒）与路标合并
// 距离 MergeDistance（米）必须为正。
type Config struct {
	InitialTime     int64   // 初始时间（毫秒）
	InitialX        float64 // 初始位置 X（米，地图坐标）
	InitialY        float64 // 初始位置 Y（米，地图坐标）
	InitialHeading  float64 // 初始朝向（弧度）
	InitialVariance float64 // 初始位置方差（非负）
	MaxInterval     int64   // 相邻位姿允许的最大时间间隔（毫秒，必须为正）
	MergeDistance   float64 // 路标观测合并距离（米，必须为正）
}

// Observation 是一帧中对单个路标的一次观测，位置在机器人自身坐标下。
type Observation struct {
	ID string  // 路标标识，非空
	X  float64 // 自身坐标下的 X（米）
	Y  float64 // 自身坐标下的 Y（米）
}

// Frame 是一段有序轨迹中的一帧：时间、自身坐标下的平移、朝向增量、
// 非负运动方差以及零个或多个路标观测。
type Frame struct {
	Time         int64         // 帧时间（毫秒）
	DX           float64       // 自身坐标下平移 X（米）
	DY           float64       // 自身坐标下平移 Y（米）
	DHeading     float64       // 朝向增量（弧度）
	MoveVariance float64       // 运动方差（非负）
	Observations []Observation // 零个或多个路标观测，同帧按输入次序处理
}

// Segment 是一批带有非空段标识的有序帧。
type Segment struct {
	ID     string  // 段标识，非空
	Frames []Frame // 有序帧
}

// Pose 是一份二维位姿及其位置方差。
type Pose struct {
	Time     int64
	X        float64
	Y        float64
	Heading  float64
	Variance float64
}

// Landmark 是地图坐标下的一个路标及其被接受的观测次数。
type Landmark struct {
	ID    string
	X     float64
	Y     float64
	Count int
}

// Invalidation 是一次路标失效操作：非空操作标识、非空原因与一组非空、
// 不重复的路标标识。提交时这些路标的当前有效记录同时失效，失效时间取
// 提交时的当前位姿时间。
type Invalidation struct {
	ID        string   // 操作标识，非空
	Reason    string   // 失效原因，非空
	Landmarks []string // 路标标识，非空且不重复
}

// InvalidationResult 是一次成功失效操作的结果：失效时间（提交时的当前
// 位姿时间）以及每个被撤下路标的标识与其失效的出现编号。
type InvalidationResult struct {
	Time      int64
	Landmarks []InvalidatedLandmark
}

// InvalidatedLandmark 记录一个被撤下路标的标识与被失效记录的出现编号。
type InvalidatedLandmark struct {
	ID         string
	Occurrence int
}

// Appearance 是同一标识某一次出现的记录：出现编号（同一标识首次出现为
// 1，每次失效后再次出现递增）、位置、观测计数、是否仍为当前有效记录、
// 首次观测时间，以及失效时间与原因。仍有效（Active 为真）时失效时间与
// 原因没有意义；旧文件缺少逐帧来源时 HasFirstSeen 为假，首次观测时间
// 未知。
type Appearance struct {
	Number        int // 出现编号，从 1 开始
	Landmark      Landmark
	Active        bool  // 是否为当前有效记录
	FirstSeenTime int64 // 首次观测所在帧的时间
	HasFirstSeen  bool  // 旧文件缺少逐帧来源时为假，表示首次观测时间未知
	InvalidTime   int64 // 失效时间（提交失效时的当前位姿时间）
	InvalidReason string
	InvalidOpID   string
}

// LandmarkHistory 是同一标识按出现编号递增排列的全部出现记录。
type LandmarkHistory struct {
	ID          string
	Appearances []Appearance
}

// CorrectionTarget 是已确认回环提交的目标：某个已保存帧应有的位姿与
// 非负位置方差。位置单位为米，朝向单位为弧度。
type CorrectionTarget struct {
	X        float64
	Y        float64
	Heading  float64
	Variance float64
}

// Correction 是一次已确认回环校正请求：非空标识、必须命中已导入帧的
// 锚点时间，以及该帧应有的位姿与非负位置方差。
type Correction struct {
	ID     string           // 校正标识，非空
	Anchor int64            // 已保存帧的准确时间（毫秒）
	Target CorrectionTarget // 锚点帧应有的位姿与方差
}

// PoseChange 是一帧位姿的校正前后值。
type PoseChange struct {
	Before Pose
	After  Pose
}

// LandmarkChange 是一个路标某一次出现的校正前后值（观测次数不变）。
// Occurrence 给出受影响的出现编号；同一标识的不同出现分别记录。
type LandmarkChange struct {
	ID         string
	Occurrence int
	Before     Landmark
	After      Landmark
}

// CorrectionRecord 是一次成功校正按提交次序保留的记录。后续校正可
// 覆盖相同时间范围，但先前记录永不被改写。
type CorrectionRecord struct {
	ID        string           // 校正标识
	Anchor    int64            // 锚点帧时间
	Target    CorrectionTarget // 提交目标
	EndTime   int64            // 受影响末帧时间（提交时的末帧）
	Poses     []PoseChange     // 受影响位姿的校正前后值，按时间升序
	Landmarks []LandmarkChange // 受影响路标出现的校正前后值，按标识再按出现编号升序
}

// RejectError 表示一次段导入、路标失效或回环校正因语义不合法而被整体
// 拒绝。
//
// Kind 为可区分的拒绝原因（见 Reject* 常量）；当原因涉及具体帧时，
// Frame 给出从零开始的帧序号且 HasFrame 为真；路标冲突时 Landmark
// 给出涉及的路标标识；重复段内容冲突时 Landmark 给出冲突的段标识。
// 两种情况下 HasLandmark 均为真。校正类原因用 Time 给出提交的锚点
// 时间且 HasTime 为真；校正中路标冲突时 Time 改为给出冲突观测所在帧的
// 时间、Landmark 给出路标标识、Occurrence 给出冲突的出现编号（1 起），
// HasLandmark 与 HasOccurrence 均为真。校正中某条观测转换到地图坐标后
// 出现非有限数值时同样处理：Time 为该观测所在帧的实际时间、Landmark
// 与 Occurrence 指出路标标识及其所属的出现编号。失效操作中找不到路标
// 或路标当前已失效时，Landmark 给出路标标识。
type RejectError struct {
	Kind          string
	Frame         int
	HasFrame      bool
	Landmark      string
	HasLandmark   bool
	Time          int64
	HasTime       bool
	Occurrence    int
	HasOccurrence bool
}

func (e *RejectError) Error() string {
	switch e.Kind {
	case RejectEmptySegment:
		return "posemap: segment has no frames"
	case RejectEmptyID:
		if e.HasFrame {
			return "posemap: frame " + strconv.Itoa(e.Frame) + " has empty landmark id"
		}
		return "posemap: empty segment, correction or invalidation id"
	case RejectEmptyReason:
		return "posemap: invalidation reason is empty"
	case RejectEmptyLandmarkList:
		return "posemap: invalidation landmark list is empty"
	case RejectDuplicateLandmarkEntry:
		return "posemap: invalidation lists landmark " + e.Landmark + " more than once"
	case RejectLandmarkNotFound:
		return "posemap: landmark " + e.Landmark + " not found"
	case RejectLandmarkInactive:
		return "posemap: landmark " + e.Landmark + " has no active occurrence"
	case RejectInvalidationMismatch:
		return "posemap: invalidation id " + e.Landmark + " already saved with different content"
	case RejectNegativeVariance:
		if e.HasTime {
			return "posemap: correction target variance is negative"
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " has negative motion variance"
	case RejectNonFinite:
		if e.HasTime {
			if e.HasLandmark {
				if e.HasOccurrence {
					return "posemap: correction makes observation of landmark " + e.Landmark + " occurrence " + strconv.Itoa(e.Occurrence) + " at frame time " + strconv.FormatInt(e.Time, 10) + " non-finite"
				}
				return "posemap: correction makes observation of landmark " + e.Landmark + " at frame time " + strconv.FormatInt(e.Time, 10) + " non-finite"
			}
			return "posemap: correction target or corrected result has non-finite value"
		}
		if e.HasLandmark {
			return "posemap: frame " + strconv.Itoa(e.Frame) + " has non-finite observation of landmark " + e.Landmark
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " has non-finite value"
	case RejectTimeOrder:
		if e.Frame == 0 {
			return "posemap: first frame must be later than initial time or previous segment end"
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " time is not strictly increasing"
	case RejectInterval:
		return "posemap: frame " + strconv.Itoa(e.Frame) + " exceeds the maximum time interval"
	case RejectLandmarkConflict:
		if e.HasTime {
			if e.HasOccurrence {
				return "posemap: correction conflicts landmark " + e.Landmark + " occurrence " + strconv.Itoa(e.Occurrence) + " at frame time " + strconv.FormatInt(e.Time, 10)
			}
			return "posemap: correction conflicts landmark " + e.Landmark + " at frame time " + strconv.FormatInt(e.Time, 10)
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " observation of landmark " + e.Landmark + " is beyond merge distance"
	case RejectDuplicateMismatch:
		return "posemap: segment id " + e.Landmark + " already saved with different content"
	case RejectAnchorNotFound:
		return "posemap: anchor time " + strconv.FormatInt(e.Time, 10) + " does not match an imported frame"
	case RejectCorrectionMismatch:
		return "posemap: correction id " + e.Landmark + " already saved with different content"
	case RejectNoBasis:
		return "posemap: correction range from " + strconv.FormatInt(e.Time, 10) + " lacks per-frame observation sources"
	default:
		return "posemap: request rejected (" + e.Kind + ")"
	}
}

// 可区分的拒绝原因。
const (
	RejectEmptySegment           = "empty_segment"            // 空批次
	RejectEmptyID                = "empty_id"                 // 空段/路标/校正/失效标识
	RejectEmptyReason            = "empty_reason"             // 失效原因为空
	RejectEmptyLandmarkList      = "empty_landmark_list"      // 失效路标列表为空
	RejectDuplicateLandmarkEntry = "duplicate_landmark_entry" // 失效列表中路标重复
	RejectLandmarkNotFound       = "landmark_not_found"       // 失效的路标从未出现
	RejectLandmarkInactive       = "landmark_inactive"        // 失效的路标当前无有效记录
	RejectInvalidationMismatch   = "invalidation_mismatch"    // 同一失效标识对应不同内容
	RejectNegativeVariance       = "negative_variance"        // 负运动方差或负目标方差
	RejectNonFinite              = "non_finite"               // 非有限数值（NaN/Inf）
	RejectTimeOrder              = "time_order"               // 时间未严格递增或首帧不够晚
	RejectInterval               = "interval_exceeded"        // 相邻位姿间隔超过上限
	RejectLandmarkConflict       = "landmark_conflict"        // 同标识路标超出合并距离
	RejectDuplicateMismatch      = "duplicate_mismatch"       // 同一段标识对应不同内容
	RejectAnchorNotFound         = "anchor_not_found"         // 校正锚点未命中已导入帧
	RejectCorrectionMismatch     = "correction_mismatch"      // 同一校正标识对应不同内容
	RejectNoBasis                = "no_basis"                 // 旧地图缺少逐帧观测来源
)

// 哨兵错误，供 errors.Is 使用。
var (
	// ErrClosed 在已关闭的地图上操作时返回。
	ErrClosed = errors.New("posemap: map is closed")
	// ErrInvalidConfig 在创建地图的配置不合法时返回。
	ErrInvalidConfig = errors.New("posemap: invalid config")
	// ErrInvalidRect 在矩形查询的上下界颠倒时返回。
	ErrInvalidRect = errors.New("posemap: invalid rectangle")
	// ErrNotFound 在查询时间早于初始时间（无任何不晚于它的位姿）时返回。
	ErrNotFound = errors.New("posemap: pose not found")
	// ErrLandmarkNotFound 在按标识查询路标历次出现而该标识从未出现时返回。
	ErrLandmarkNotFound = errors.New("posemap: landmark not found")
	// ErrCorrupt 在数据文件损坏、截断或校验失败时返回。
	ErrCorrupt = errors.New("posemap: corrupt data file")
	// ErrUnsupportedVersion 在数据文件格式版本不受支持时返回。
	ErrUnsupportedVersion = errors.New("posemap: unsupported file format version")
)

// normalizeAngle 把任意角度归一到 [-π, π)。
//
// 已经落在范围内的角度原样返回（零保持零，-π 保持 -π，已经可表示的微小
// 角度也不被当舍入误差丢掉）；只有范围外的角度才按整圈 2π 平移回范围。
// 不能先把角度加上或减去 π 再取模——例如 1e-16 加 π 后低位被 π 的精度
// 吞掉，再减回 π 时微小转角就变成了零，连续多帧的小转向因此无法累积。
// 同理，整圈附近的输入（如 2π 之外还差一个最小可表示转角的 6.283185307179587）
// 若先加 π，相对整圈的微小余量会被约 9.42 的精度吞掉而变成零；必须先对
// 整圈取精确余数，再平移进范围。
func normalizeAngle(a float64) float64 {
	if a == 0 {
		return 0 // 零保持零，-0 也规范成 +0。
	}
	if -math.Pi <= a && a < math.Pi {
		return a
	}
	// 范围外（含 +π）：先取对整圈 2π 的余数，再平移进 [-π, π)。
	// math.Mod 的结果是精确余数，不向 π 平移，整圈上下一个最小可表示
	// 转角的余量（±8.881784197001252e-16 等）都完整保留；余数落在
	// (-2π, 2π)，至多再平移一次整圈即入范围。整圈附近的余数与这次
	// 平移都是同量级浮点减法（Sterbenz），结果精确、不丢失微小转角；
	// 恰好一整圈得到零。a 为非有限值时结果为 NaN，由调用方按非有限拒绝。
	r := math.Mod(a, 2*math.Pi)
	if r >= math.Pi {
		// 含 +π：+π 不属于 [-π,π)，折回 -π 一侧，二者物理方向完全相同。
		r -= 2 * math.Pi
	} else if r < -math.Pi {
		r += 2 * math.Pi
	}
	if r == 0 {
		return 0 // 负整圈的余数是 -0，规范成 +0。
	}
	return r
}

// isFinite 判断数值既不是 NaN 也不是 Inf。
func isFinite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }

// mergeMean 把一个新样本 v 并入既有等权均值（已有 count 个样本），
// 返回 count+1 个样本的均值。与 (mean*count + v)/(count+1) 数学等价，
// 但按 mean + (v-mean)/(count+1) 计算：大数值坐标下 mean*count 会溢出
// 为无穷，而这里每一步都只是有限值之间的凸组合，结果保持有限且落在
// 参与平均的坐标范围内。调用方须保证 v 与 mean 均为有限值且二者之差
// 有限（被接受的观测与当前均值相距不超过有限的合并距离，自然满足）。
func mergeMean(mean, v float64, count int) float64 {
	return mean + (v-mean)/float64(count+1)
}

// localToMap 把机器人自身坐标下的点 (lx, ly) 按给定地图坐标位姿
// 转换到地图坐标：旋转 heading 后平移。
func localToMap(px, py, heading, lx, ly float64) (float64, float64) {
	c, s := math.Cos(heading), math.Sin(heading)
	return px + c*lx - s*ly, py + s*lx + c*ly
}

